// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#pragma once#include "Common/GraphicsPipelineStage.h"#include "Common/FullscreenPass.h"#include "Common/PrimitiveRenderPass.h"#include "Common/UtilityPasses.h"struct SHDRStreaksParams;class CBloomStage : public CGraphicsPipelineStage{public:	static const EGraphicsPipelineStage StageID = eStage_Bloom;	//! Ray count ceiling for the diffraction streaks, mirrored by CHDRStreaks::s_nMaxDirections.	static const int kMaxStreakDirections = 12; //!< Line passes; each paints two opposed spikes (24 max).	//! Stretch iterations per ray. Each one widens the tap stride by the tap count, so two	//! iterations of 8 taps already reach 63 tap distances from the source.	static const int kStreakIterations = 2;	//! Stretch iterations for the anamorphic horizontal flare. One more than the blade streaks:	//! 8^3 tap distances span the whole frame width, which is what makes the line read as a	//! single stroke across the frame instead of a stubby spike.	static const int kAnamorphicIterations = 3;	//! Gaussian iterations for the halation halo, run at 1/16 resolution. CGaussianBlurPass has	//! a fixed 16 tap footprint (+-8 texels) whatever its distribution, so the halo's WIDTH comes	//! from the resolution it runs at (+-8 texels at 1/16 = +-128 full-res pixels), and being a	//! true separable Gaussian it is isotropic - a round halo, as emulsion scatter is.	static const int kHalationBlurIterations = 2;	CBloomStage(CGraphicsPipeline& graphicsPipeline)		: CGraphicsPipelineStage(graphicsPipeline)		, m_pass1H(&graphicsPipeline)		, m_pass1V(&graphicsPipeline)		, m_pass2H(&graphicsPipeline)		, m_pass2V(&graphicsPipeline)		, m_passStreakThreshold(&graphicsPipeline)		, m_passAnamorphicThreshold(&graphicsPipeline)		, m_passFilterThreshold(&graphicsPipeline)		, m_passDiffractionThreshold(&graphicsPipeline)		, m_passDiffractionBlurH(&graphicsPipeline)		, m_passDiffractionBlurV(&graphicsPipeline)		, m_passDiffractionDebug(&graphicsPipeline)		, m_passDiffractionComposite(&graphicsPipeline)		, m_passDiffractionSourceStats(&graphicsPipeline)		, m_passDiffractionStatsReduce(&graphicsPipeline)		, m_passDiffractionBudget(&graphicsPipeline)		, m_passDiffractionReadbackCopy(&graphicsPipeline)		, m_passHalationThreshold(&graphicsPipeline)		, m_passHalationDown0(&graphicsPipeline)		, m_passHalationDown1(&graphicsPipeline)		, m_passHalationBlur(&graphicsPipeline)		, m_passHalationComposite(&graphicsPipeline)	{		for (int direction = 0; direction < kMaxStreakDirections; ++direction)		{			for (int iteration = 0; iteration < kStreakIterations; ++iteration)				m_passStreakStretch[direction][iteration].SetGraphicsPipeline(&graphicsPipeline);		}		for (int iteration = 0; iteration < kAnamorphicIterations; ++iteration)			m_passAnamorphicStretch[iteration].SetGraphicsPipeline(&graphicsPipeline);	}	bool IsStageActive(EShaderRenderingFlags flags) const final	{		return CRenderer::CV_r_HDRBloom && CRenderer::CV_r_PostProcess;	}	void Execute();	//! Adds the wave-glare layer into the HDR target. Called by the pipeline right after	//! Execute(), in the same window as the DOF's ghost composite: the glare has its own	//! half-resolution layer now instead of travelling through $HDRFinalBloom, so it needs its	//! own composite. Consume-once, and a no-op in every frame the glare pass did not run.	void ExecuteDiffractionComposite();private:	//! Everything r_HDRDiffractionDebug 3's once-a-second report needs in order to say, in plain	//! numbers, why the rays are as bright as they are. Filled by ExecuteDiffraction from the	//! values that frame actually used and handed to the readback, which prints it when the	//! source's peak comes back from the GPU a frame or two later. One struct rather than eight	//! arguments, and it is captured at ISSUE time so the peak and the parameters that produced	//! it can never be a frame apart.	struct SDiffractionReport	{		float fThreshold = 0.0f;          //!< resolved, in exposed units		float fThresholdStops = 0.0f;     //!< the same number as stops over mid grey		float fGain = 1.0f;               //!< resolved Streak Amount (2^stops under the switch)		float fGainSlider = 0.0f;         //!< what the user typed		float fGlareFraction = 0.0f;      //!< texture + tail, BEFORE the sprite's inner fade		float fInnerKept = 1.0f;          //!< what the inner fade leaves of the texture's share		float fRayCoeff = 0.0f;           //!< deposit along a SPIKE  = excess * gain * this		float fRingMeanCoeff = 0.0f;      //!< deposit at the ring MEAN, same radius		float fReportRadiusHalfPx = 0.0f; //!< where those two are evaluated		float fNativeScale = 2.0f;        //!< half-res px -> native px		bool  bFullResSource = false;		bool  bSceneReferred = false;		int   nSourceW = 0;		int   nSourceH = 0;		int   nGridW = 0;                 //!< the half-res sprite grid, which is what the peak's (x, y) index		int   nGridH = 0;		// The source BUDGET (decisions/s8-glare-budget.md). These four come back from the GPU's		// own arithmetic over the same frame's source, not from an estimate: the cost of this		// pass is one large sprite per texel above the threshold, so the population IS the		// performance and it has to be measurable whether the budget is on or off.		bool  bStatsValid = false;        //!< the 1x1 stats texel made it back this cycle		bool  bBudgetActive = false;      //!< r_HDRDiffractionMaxSources > 0 AND scene-referred		int   nBudget = 0;                //!< the budget actually IN FORCE, after the hard cap		int   nBudgetRequested = 0;       //!< r_HDRDiffractionMaxSources as the user set it		//! GPU time of the glare passes, milliseconds, from the render pipeline profiler's		//! HDR_DIFFRACTION / HDR_DIFFRACTION_COMPOSITE sections. Negative means the profiler was		//! not recording this frame, which is the normal state - it costs timestamps, so it is		//! only on with r_profiler or r_DisplayInfo 3. The report says which.		float fGlareGpuMs = -1.0f;        //!< sprite pass, budget chain included (they nest)		float fCompositeGpuMs = -1.0f;    //!< the layer's composite into the HDR target		float fRawSources = 0.0f;         //!< texels over the threshold BEFORE any budgeting		float fBudgetSources = 0.0f;      //!< of those, how many still drew a sprite		float fResidualEnergyFrac = 0.0f; //!< share of the source excess that lost its star		float fCutoff = 0.0f;             //!< the energy cutoff in force, exposed units		float fSpriteHalfPx = 0.0f;       //!< sprite half extent in half-res px: population x this squared IS the fill	};	void ExecuteStreaks();	void ExecuteDiffraction(const SHDRStreaksParams& streakParams, float fBloomCompositeWeight);	//! The source budget's reduction chain. Returns the 1x1 stats texture the sprite vertex	//! shader must read (never null once the targets exist), after updating this frame's cutoff.	CTexture* ExecuteDiffractionBudget(CTexture* pSource, int nBudget);	void UpdateDiffractionSourceReadback(int nDebugMode, CTexture* pSource, const SDiffractionReport& report);	//! Reads this frame's HDR_DIFFRACTION / HDR_DIFFRACTION_COMPOSITE GPU times out of the render	//! pipeline profiler's detailed sections, so the report can print the COST next to the count.	//! Leaves the fields negative when the profiler is not recording.	static void SampleDiffractionGpuTimes(SDiffractionReport& report);	//! r_HDRDiffractionDebug 3's once-a-second answer to "why are the rays that bright", in	//! exposed scene units and stops over mid grey.	static void PrintDiffractionReport(const SDiffractionReport& report, float fMaxExcess, int nMaxX, int nMaxY);	void ExecuteFilterPSF();	void ExecuteHalation();	CFullscreenPass m_pass1H;	CFullscreenPass m_pass1V;	CFullscreenPass m_pass2H;	CFullscreenPass m_pass2V;	CFullscreenPass m_passStreakThreshold;	CFullscreenPass m_passStreakStretch[kMaxStreakDirections][kStreakIterations];	CFullscreenPass m_passAnamorphicThreshold;	CFullscreenPass m_passAnamorphicStretch[kAnamorphicIterations];	// Front filter PSF: a threshold pass into the shared scratch target, then one sprite draw	// per bright quarter-resolution texel. The sprites are procedural geometry expanded from	// SV_VertexID, so the pass needs a primitive pass and a per-view constant buffer of its	// own describing the quarter-resolution GRID (the DOF's splat and ghost passes do the	// same for their grids).	CFullscreenPass      m_passFilterThreshold;	CPrimitiveRenderPass m_passFilterPSF;	CRenderPrimitive     m_filterPSFPrimitive;	CConstantBufferPtr   m_pFilterPSFPerViewCB;	// Wave-optics diffraction glare (DiffractionKernelSpec.md). Same sparse convolution shape as	// the front filter above - a threshold pass and one sprite per surviving source texel - but	// the pattern is not authored: it is the FFT of the pupil, built by the DOF stage's job,	// sampled radially and extrapolated past its own edge by the edge-diffraction law. The debug	// pass draws that kernel into the corner of the frame.	//	// Everything here runs at HALF resolution and into a layer of its own, unlike the rest of the	// glare family. At quarter resolution a lamp is a 3x3 block of thresholded texels, each of	// which spawns a sprite, so the SUM of those sprites has the block's square as its centre;	// and the deposit was then bilinearly magnified 4x onto the pattern's steepest slope, which	// is what put visible square blocks around every source. Half resolution halves both errors	// in each axis, and the source pre-blur below turns the block into a round blob.	CFullscreenPass      m_passDiffractionThreshold;	CFullscreenPass      m_passDiffractionBlurH;	CFullscreenPass      m_passDiffractionBlurV;	CPrimitiveRenderPass m_passDiffraction;	CRenderPrimitive     m_diffractionPrimitive;	CConstantBufferPtr   m_pDiffractionPerViewCB;	CFullscreenPass      m_passDiffractionDebug;	CFullscreenPass      m_passDiffractionComposite;	// The source BUDGET's reduction chain (decisions/s8-glare-budget.md). Three passes, of which	// only the first reads the frame: source -> 8x8 tile stats -> a fixed 16x16 -> one texel	// holding (cutoff, raw count, count above the cutoff, share of the excess below it). The	// sprite vertex shader samples that one texel; the budget therefore costs no readback and	// has no CPU round trip in it. The 1x1 is ping-ponged because the last pass has to read the	// PREVIOUS cutoff in order to correct it, and a pass may not read the target it writes.	CFullscreenPass      m_passDiffractionSourceStats;	CFullscreenPass      m_passDiffractionStatsReduce;	CFullscreenPass      m_passDiffractionBudget;	// Half-resolution glare targets: the thresholded (and pre-blurred) source, its separable	// blur scratch, and the RGBA16F layer the sprites deposit into. Allocated lazily like the	// halation targets, so Analytic mode and glare off cost nothing.	_smart_ptr<CTexture> m_pTexDiffractionSource;	_smart_ptr<CTexture> m_pTexDiffractionSourceTemp;	_smart_ptr<CTexture> m_pTexDiffractionLayer;	// The budget's three stats targets. Tiny (a 1080p half-res grid reduces to 120 x 68), and	// RGBA32F because the middle two carry COUNTS of up to half a million alongside a summed	// HDR excess - fp16 runs out of both mantissa and range long before that.	_smart_ptr<CTexture> m_pTexDiffractionTileStats;   //!< ceil(w/8) x ceil(h/8)	_smart_ptr<CTexture> m_pTexDiffractionStatsMid;    //!< fixed 16 x 16, so the last pass is a fixed 256 taps	_smart_ptr<CTexture> m_pTexDiffractionStats[2];    //!< 1 x 1 ping-pong, also the readback source	int                  m_nDiffractionStatsIndex = 0;	int                  m_diffractionLayerWidth = 0;	int                  m_diffractionLayerHeight = 0;	bool                 m_bDiffractionLayerValid = false;	bool AcquireDiffractionTargets(int halfWidth, int halfHeight);	void ReleaseDiffractionTargets();	// r_HDRDiffractionDebug 3 also reports the brightest source on screen in the log. The	// thresholded source is a GPU texture, so the number has to come back over a staging copy:	// blit the quarter-resolution excess into a readback target once a second, issue the	// download, and map it a few frames later when the fence has signalled. Nothing here stalls	// the pipeline, and none of it is allocated unless the mode is on.	CStretchRectPass     m_passDiffractionReadbackCopy;	_smart_ptr<CTexture> m_pTexDiffractionReadback;	bool                 m_bDiffractionReadbackIssued = false;	bool                 m_bDiffractionReadbackStalled = false;	float                m_fDiffractionReadbackTime = 0.0f;	//! The 1x1 budget stats travel back on the SAME cadence and in the same cycle as the source	//! blit above - sixteen bytes, issued in the same frame, so if the source's fence has	//! signalled this one certainly has. It is what puts a measured population in the report.	_smart_ptr<CTexture> m_pTexDiffractionStatsInFlight;	//! Captured when the download is issued, printed when it lands: the numbers that produced	//! the peak the GPU is on its way back with.	SDiffractionReport   m_diffractionReportInFlight;	CFullscreenPass   m_passHalationThreshold;	CStretchRectPass  m_passHalationDown0;   // quarter -> 1/8	CStretchRectPass  m_passHalationDown1;   // 1/8 -> 1/16	CGaussianBlurPass m_passHalationBlur;	CFullscreenPass   m_passHalationComposite;	// Low-resolution halation targets (the shared HDR chain stops at quarter resolution).	// Allocated lazily, so halation off costs nothing.	_smart_ptr<CTexture> m_pTexHalationEighth;	_smart_ptr<CTexture> m_pTexHalationLow;	_smart_ptr<CTexture> m_pTexHalationLowTemp;	int                  m_halationLowWidth = 0;	int                  m_halationLowHeight = 0;	bool AcquireHalationTargets(int quarterWidth, int quarterHeight);	void ReleaseHalationTargets();};